  const COMPETITOR_SOURCE_TYPES={official_site:'موقع رسمي',maps:'Google Maps',social:'حساب سوشيال',booking:'منصة حجز',ad_library:'مكتبة إعلانات',directory:'دليل خارجي',other:'مصدر خارجي'};
